import os, json, glob, time

A_PATH = "storage/shared/quantum_probe/manifests/kairos/c773848143.json"

def pick_volition_manifest():
    # Try plausible subdirs
    candidates = []
    for sub in ["volition_iv", "volition", "volition4", "volition_v4", "volitioniv"]:
        d = os.path.join("storage/shared/quantum_probe/manifests", sub)
        if os.path.isdir(d):
            for fp in glob.glob(os.path.join(d, "*.json")):
                try:
                    mt = os.path.getmtime(fp)
                except Exception:
                    mt = 0.0
                candidates.append((mt, fp))
    if not candidates:
        return None
    candidates.sort()
    return candidates[-1][1]

def load(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def index_files(m):
    files = m.get("files") or []
    by_path = {}
    for rec in files:
        p = (rec.get("path") or "").replace("\\", "/")
        by_path[p] = {
            "size": rec.get("size"),
            "sha256": rec.get("sha256"),
            "read_ok": rec.get("read_ok"),
        }
    return by_path

def summarize(a_path, b_path):
    A = load(a_path)
    B = load(b_path)
    a_idx, b_idx = index_files(A), index_files(B)
    a_set, b_set = set(a_idx), set(b_idx)
    only_in_a = sorted(a_set - b_set)
    only_in_b = sorted(b_set - a_set)
    common = sorted(a_set & b_set)
    hash_mismatches = []
    size_mismatches = []
    read_mismatches = []
    for p in common:
        a = a_idx[p]; b = b_idx[p]
        if (a.get("read_ok") is True) != (b.get("read_ok") is True):
            read_mismatches.append({"path": p, "a": a.get("read_ok"), "b": b.get("read_ok")})
        if a.get("sha256") and b.get("sha256") and a.get("sha256") != b.get("sha256"):
            hash_mismatches.append({"path": p, "a": a.get("sha256"), "b": b.get("sha256")})
        if (a.get("size") is not None) and (b.get("size") is not None) and a.get("size") != b.get("size"):
            size_mismatches.append({"path": p, "a": a.get("size"), "b": b.get("size")})
    summary = {
        "a": {"path": a_path, "lineage": load(a_path).get("lineage"), "import_ok": load(a_path).get("import_ok"),
              "file_count": load(a_path).get("file_count"), "exists_count": load(a_path).get("exists_count")},
        "b": {"path": b_path, "lineage": load(b_path).get("lineage"), "import_ok": load(b_path).get("import_ok"),
              "file_count": load(b_path).get("file_count"), "exists_count": load(b_path).get("exists_count")},
        "path_diff": {
            "only_in_a_count": len(only_in_a),
            "only_in_b_count": len(only_in_b),
            "only_in_a_sample": only_in_a[:20],
            "only_in_b_sample": only_in_b[:20],
        },
        "mismatch_counts": {"hash": len(hash_mismatches), "size": len(size_mismatches), "read_ok": len(read_mismatches)},
        "mismatch_samples": {
            "hash": hash_mismatches[:20], "size": size_mismatches[:20], "read_ok": read_mismatches[:20],
        },
    }
    return summary

def main():
    b_path = pick_volition_manifest()
    if b_path is None:
        print("DIFF_RESULT: NO_VOLITION_MANIFEST_FOUND")
        return
    if not os.path.exists(A_PATH):
        print("DIFF_RESULT: KAIROS_MANIFEST_MISSING")
        return
    S = summarize(A_PATH, b_path)
    print("DIFF_SUMMARY", json.dumps(S, ensure_ascii=False))
    diverged = any([
        S["path_diff"]["only_in_a_count"] > 0,
        S["path_diff"]["only_in_b_count"] > 0,
        S["mismatch_counts"]["hash"] > 0,
        S["mismatch_counts"]["size"] > 0,
        S["mismatch_counts"]["read_ok"] > 0,
        S["a"].get("import_ok") != S["b"].get("import_ok"),
    ])
    print("DIFF_RESULT:", "DIVERGENCE" if diverged else "MATCH")

if __name__ == "__main__":
    main()
